mapper.select:
SELECT
    id, trace_id, operator, operator_id, action, action_name,
    target_type, target_id, target_name,
    http_method, request_uri, client_ip,
    result, error_code, error_msg, cost_ms, created_time
FROM sys_auth_audit_log


        AND operator LIKE CONCAT(#{q.operator}, '%')


        AND action = #{q.action}


        AND target_name LIKE CONCAT(#{q.targetName}, '%')


        AND result = #{q.result}


        AND created_time >= #{q.beginTime}


        AND created_time <= #{q.endTime}


ORDER BY created_time DESC, id DESC
